patterns.recipe:
// 1. CAPTURE (before the rollout) - persist output to a file outside the cluster
kubectl_get({resourceType: '<WORKLOAD_KIND>', name: '<WORKLOAD_NAME>', namespace: '<NAMESPACE>', output: 'yaml'})
kubectl_get({resourceType: 'replicasets', namespace: '<NAMESPACE>', labelSelector: '<SELECTOR>', output: 'yaml'})   // or resourceType:'controllerrevisions' for statefulset/daemonset
kubectl_generic({command: 'get', resourceType: 'replicasets', namespace: '<NAMESPACE>', args: ['-l','<SELECTOR>','-o','jsonpath={range .items[*]}{.metadata.name} rev={.metadata.annotations.deployment\\.kubernetes\\.io/revision} replicas={.spec.replicas} uid={.metadata.uid}{"\\n"}{end}']})
// pinned: revision=<CAPTURED_REVISION>, replicaset=<CAPTURED_RS_NAME>, paused=<CAPTURED_PAUSED>

// 2a. RESTORE after undo or restart - re-resolve <CAPTURED_RS_NAME> to its CURRENT number first, then:
kubectl_rollout({subCommand: 'undo', resourceType: '<WORKLOAD_KIND>', name: '<WORKLOAD_NAME>', namespace: '<NAMESPACE>', revision: <CAPTURED_REVISION>})

// 2b. RESTORE after pause (captured paused was absent/false):
kubectl_rollout({subCommand: 'resume', resourceType: '<WORKLOAD_KIND>', name: '<WORKLOAD_NAME>', namespace: '<NAMESPACE>'})
// 2b'. RESTORE after resume (captured paused was true):
kubectl_rollout({subCommand: 'pause', resourceType: '<WORKLOAD_KIND>', name: '<WORKLOAD_NAME>', namespace: '<NAMESPACE>'})

// 2c. FALLBACK when the captured revision was pruned (does NOT clear restartedAt):
kubectl_apply({namespace: '<NAMESPACE>', manifest: `<SAVED_MANIFEST_YAML>`})

// 3. VERIFY - diff .spec against the artifact
kubectl_get({resourceType: '<WORKLOAD_KIND>', name: '<WORKLOAD_NAME>', namespace: '<NAMESPACE>', output: 'yaml'})
kubectl_rollout({subCommand: 'status', resourceType: '<WORKLOAD_KIND>', name: '<WORKLOAD_NAME>', namespace: '<NAMESPACE>'})

// Preferred: do not call cleanup for teardown at all. Track what you create and reverse it explicitly:
//   record {kind, name, namespace} for every object you create, then
mcp__k8s__kubectl_delete({resourceType:'<KIND>', name:'<NAME>', namespace:'<NAMESPACE>'})   // per recorded object; see the kubectl_delete pattern for capture-before-delete

// If cleanup must be called on an UNKNOWN build, there is no in-protocol way to preview it. The only safe preparation is:
mcp__k8s__kubectl_generic({command:'get', resourceType:'deployments,services,configmaps,secrets,serviceaccounts,pvc,statefulsets,daemonsets,jobs,cronjobs', allNamespaces:true, args:['-o','custom-columns=NS:.metadata.namespace,KIND:.kind,NAME:.metadata.name,UID:.metadata.uid']})   // uid-pinned inventory -> file
// ... original action: mcp__k8s__cleanup({}) ...
// CHECK: repeat the same uid-pinned listing and diff. On this build the diff is EMPTY.
